-- 20261009_brain_estimate_models.sql — automatic team and investment estimates (resolver ar-1.5.0)
-- Two Brain methods, stored as labelled estimates (judgment, low confidence). Used when a founder asks
-- Za3fran to estimate the team or the investment. One review-queue entry each (method_change);
-- nothing waits for the review.
insert into brain_parameters (key, scope, grp, level, label_en, label_fr, unit, value_type, qualifier_kind, fav, refresh_months, regulatory, engine_path, notes) values
 ('benchmark.staffing_model','format','benchmark',null,'Staffing method (team estimate)','Méthode de dimensionnement de l''équipe','json','json',null,null,12,false,'labour.roster (estimate mode)','Fixed roles per venue plus on-duty positions per service; headcount = weekly hours / legal week (lib/estimates.js).'),
 ('benchmark.capex_model','local','benchmark','country','Investment estimate method','Méthode d''estimation de l''investissement','json','json','format',null,12,false,'investment (estimate mode)','Qualifier = format key. Rates per m², per seat, lump sums, percentages and pre-opening months (lib/estimates.js).')
on conflict (key) do nothing;
insert into brain_parameter_values (parameter_key, market_id, format_key, qualifier, value_json, unit, currency, source_class, status, source_name, observed_at, confidence, researched_by, review_note, refresh_due_at) values
 ('benchmark.staffing_model', null, 'bistro_wine_bar', '', '{"version":"sm-1","overtime_tolerance":0.2,"service_hours":{"lunch":{"base":5,"low":4.5,"high":6},"dinner":{"base":6.5,"low":6,"high":7.5},"default":{"base":6,"low":5,"high":7}},"fixed":[{"role":"chef","count":1,"covers":["cook"],"note":"One head chef per venue; works the line (covers cook hours)"},{"role":"manager","count":1,"covers":["server"],"founder_replaces":true,"note":"One floor manager per venue; covers one floor position"}],"on_duty":[{"role":"server","seats_per":{"base":18,"low":15,"high":22}},{"role":"cook","seats_per":{"base":25,"low":20,"high":30}},{"role":"commis","count":1,"min_seats":40},{"role":"kitchen_porter","count":1},{"role":"bartender","count":1,"alcohol_only":true}]}'::jsonb, 'json', null, 'estimate', 'researched', 'Za3fran judgment, 9 Oct 2026: method calibrated on the Canaille estimates researched on 8 Oct 2026 (French ranges scaled, one Moroccan consultancy blog, generic industry ratios). Secondary and foreign sources; no Moroccan benchmark found.', '2026-10-09', 'low', 'claude', 'ESTIMATE, JUDGMENT. Service hours include set-up and close. Ratios are generic industry figures, not Moroccan. Reproduces the 8 Oct Canaille team (chef, 2 cooks, commis, porter, 3 servers, bartender, founder on the floor).', '2027-10-09'),
 ('benchmark.capex_model', '6e6218db-0e40-4fc9-9528-30465935d145', null, 'bistro_wine_bar', '{"version":"cm-1","m2_per_seat":{"base":3.4,"low":3,"high":4},"lines":[{"key":"fitout","category":"fitout","per":"m2","base":3000,"low":2500,"high":4500,"label":"Travaux et aménagement / Works and fit-out","note":"Moroccan anchor is one consultancy blog figure for a 200 m² food unit"},{"key":"kitchen_equipment","category":"equipment","per":"seat","base":7000,"low":5000,"high":10000,"label":"Équipement de cuisine / Kitchen equipment","note":"French range for a traditional restaurant, scaled; no Moroccan source"},{"key":"furniture","category":"furniture","per":"seat","base":3000,"low":2000,"high":5000,"label":"Mobilier, décoration, éclairage / Furniture, decor, lighting","note":"French range scaled to local manufacture; judgment"},{"key":"bar_wine","category":"equipment","per":"lump","base":120000,"low":80000,"high":180000,"alcohol_only":true,"label":"Équipement de bar / Bar equipment","note":"Wine storage, ice machine, glass washer, coffee machine; judgment"},{"key":"tableware","category":"equipment","per":"seat","base":1200,"low":800,"high":1800,"label":"Arts de la table / Tableware, glassware, linen","note":"Judgment"},{"key":"it","category":"it","per":"lump","base":50000,"low":30000,"high":80000,"label":"Informatique et encaissement / IT, payments, sound, cameras","note":"Judgment"},{"key":"architect","category":"fitout","per":"pct_of","of":["fitout"],"base":0.1,"low":0.07,"high":0.15,"label":"Honoraires d''architecte / Architect and design fees","note":"Judgment"},{"key":"setup_legal","category":"preopening","per":"lump","base":40000,"low":20000,"high":70000,"label":"Création, notaire, bail / Company set-up, notary, lease","note":"Judgment"},{"key":"initial_stock","category":"initial_stock","per":"seat","base":1000,"low":700,"high":1500,"alcohol_extra_per_seat":{"base":2000,"low":1300,"high":2900},"label":"Stock initial / Opening stock","note":"No Moroccan wholesale prices found; judgment"},{"key":"preopening","category":"preopening","per":"preopening","payroll_months":{"base":1,"low":1,"high":1.5},"chef_extra_months":{"base":1,"low":0.5,"high":2},"works_months":{"base":3,"low":2,"high":4},"launch_marketing":{"base":40000,"low":20000,"high":80000},"label":"Frais de pré-ouverture / Pre-opening costs"},{"key":"contingency","category":"contingency","per":"pct_of","of":["fitout","architect","kitchen_equipment","furniture","bar_wine","tableware"],"base":0.1,"low":0.05,"high":0.15,"label":"Imprévus / Contingency","note":"A Moroccan works guide recommends 15%"}]}'::jsonb, 'json', 'MAD', 'estimate', 'researched', 'Za3fran judgment, 9 Oct 2026: method calibrated on the Canaille estimates researched on 8 Oct 2026 (French ranges scaled, one Moroccan consultancy blog, generic industry ratios). Secondary and foreign sources; no Moroccan benchmark found.', '2026-10-09', 'low', 'claude', 'ESTIMATE, JUDGMENT. Rates in MAD excl. VAT. Fit-out per m², equipment and furniture per seat, pre-opening from the team and rent. Replace with founder quotes or the Installation & Equipment tool when available.', '2027-10-09');
insert into brain_review_queue (value_id, parameter_key, reason, detail)
 select id, parameter_key, 'method_change', jsonb_build_object('note','New method: automatic estimates (resolver ar-1.5.0). Plans use it immediately; review when convenient.')
 from brain_parameter_values where parameter_key in ('benchmark.staffing_model','benchmark.capex_model') and status='researched';
